// (s137 stitch) THE SUMMON TABLE. One row per KH2 summon; the state machine in sora_summon.h, the FPS file and the Summon menu read the row of
// the summon that is out (SMD()). Row 0 = Chicken Little (identical to the s136/s137 constants), row 1 = Stitch, row 2 = Genie, row 3 = Peter Pan (+ Tinker Bell).
// Their extra fields (sfx_base ... genie) are optional and live at the END of SmDef; the code that uses them is sora_summon_pp.h.
// Per row: data files (data/forms), mset slot map, attack list with hit windows (clock = the baked 60 Hz motion clock), cue table, reach numbers,
// the KH2 cast command + cost, the Limit command, the unlock rule, the menu name.
// Notes: recon/S137_HELPER_STITCH.md (Stitch's sources, GUESS list), recon/S136_HELPER_SUMMON2.md (Chicken Little).
#pragma once
#include "sora_summon_fx.h"      // SmCue + Chicken Little's cues
#include "sora_summon_fx_st.h"   // Stitch's cues (generated by tools_s137stitch/stitchfx.py)
#include "sora_summon_fx_gn.h"   // (s138 ppgenie) Genie's cues + effect sounds (tools_s137sumdata/gen_cues.py)
#include "sora_summon_fx_pp.h"   // (s138 ppgenie) Peter Pan's

#define SM_NDEF 4
#define SM_MAXCUE 160   // (s138 ppgenie: Genie has 127 cue rows)
enum { SMU_GLIDER, SMU_BEAST1, SMU_BEAST4, SMU_MSWORD, SMU_RUTA, SMU_MEDOH, SMU_RUDANIA, SMU_NABORIS };   // unlock rules. s147 user pick (themed beasts): Chicken Little = the paraglider, Stitch = Vah Ruta (water), Genie = Vah Naboris (Gerudo desert ~ Agrabah), Peter Pan = Vah Medoh (Rito, flying). Old S132 rules: Stitch 1st beast, Genie 4th, Peter Master Sword
typedef struct { float a, b; int power, n; int atkp, react, kb1, kb2; } SmHitW;  // a hit window of an attack: clock a..b, KH Power, n = hits per target in it (0 = 1);
                                                                         // (s138) atkp > 0: this window's own 00battle.bin row + its EnemyReaction / KnockbackStrength pair (else the row's)
typedef struct { int slot, nwin; SmHitW win[16]; } SmAtk;                // an attack motion with its windows (GUESS windows; see each row)
typedef struct {
    const char *name;                                                    // menu row / logs
    const char *model, *pose, *motion, *callpose, *callmotion;           // files in SM_DATA
    int need;                                                            // draw actors the exe must have (14 before the summons + 2 per row up to this one)
    int idle, walk, run, entry, exit, call, call_end;                    // mset slots (exit < 0: no exit motion, see exit_cue / exit_frames)
    int exit_cue;                                                        // exit < 0: the cue-table slot fired at the dismiss (frame 0)
    float exit_frames;                                                   // exit < 0: how long he stays drawn after the dismiss starts
    int natk;
    SmAtk atk[4];                                                        // the attack cycle (combo % natk)
    const SmCue *cues;
    int ncues;
    float shape;                                                         // blob shadow radius
    float stop_cm, atk_cm, hit_r_cm, hit_dy_cm;                          // GUESS reach numbers
    int atkp, react, kb1, kb2;                                           // atkp > 0: the hits use this 00battle.bin row's reaction (EnemyReaction / KnockbackStrength) via ah_hit, as fp_hit_enemy;
                                                                         //   0 = the old party hit (linkpos_damage_enemy_ex F54_PARTY: Chicken Little, user-verified)
    int ranged;                                                          // 1: his windows are SHOTS (Stitch's plasma blasters, bdx trap_stitch_shot_effect): they hit the AI's target within hit_r_cm, no arc check
    int entry_shift;                                                     // 1: the entry's travel is in the pose (bone 0 is not root-stripped): the cast places the origin so he ends on the follow spot
    float start_left, start_ahead;                                       // cm: where the origin starts (entry_shift 0) / where the entry ENDS (entry_shift 1), left of / ahead of Sora
    int cast_cmd, limit_cmd;                                             // KH2 command ids: the cast (Execute 72, Cost 3 Drive bars) and the Limit
    int fps;                                                             // 1: the Limit is FPS Mode (sora_summon_fps.h); 0: not built (greyed)
    int ohana;                                                           // (s138) 1: the Limit is Ohana! (sora_summon_ohana.h: Stitch, cmd 519 + 525 Shoot / 526 Ukulele / 527 Blast)
    int unlock;
    // ---- (s138 ppgenie) all optional (0 = the old behaviour); appended so the Stitch Limit branch's edits above merge cleanly
    int sfx_base;                                                        // > 0: sfx.bin triggers at sfx_base + mset slot (sora_sfx_motion) play this row's sounds / voices (Peter 95000, Genie 97000)
    const SmFxSe *fxse; int nfxse;                                       // effect element -> its own sound (PAX se field), played when the cue spawns it
    int loop_from;                                                       // 1: a looping idle / move motion restarts at its baked loop frame (Mot.loop), not at 0 (Peter's 10A / 14A)
    int limit_label;                                                     // > 0: the page-2 Limit slot's cmd.bin label while this summon is out (0 = the old rule)
    int tink;                                                            // 1: Peter's intro has Tinker Bell (sora_summon_pp.h); she needs 1 more draw actor (her body)
    int genie;                                                           // 1: Genie: 4 Drive-Form versions in one mesh (sora_summon_pp.h)
    int attach;                                                          // (s138 review) 1: KH2 attaches him to Sora for the entry (obj_attach 0x4002): the origin = Sora's feet at the
                                                                         //   cast (start_left / start_ahead unused); entry_shift then moves it to where his last entry frame stands
    int neverland;                                                       // (s139) 1: the Limit is Never Land (sora_summon_nl.h: Peter Pan, cmd 468 + 470 / 471 / 479 / 482)
} SmDef;

